from pathlib import Path
import json,hashlib,collections
R=Path(__file__).resolve().parent;REPO=R.parents[1]
base=json.loads((R/'baseline.json').read_text()); parent=(REPO/'launch/collection-repairs/dispositions.json').read_bytes();allrows=json.loads(parent)
reviews={x['id']:x for who in ['a','b'] for x in json.loads((R/f'reviewer-{who}/findings.json').read_text())['findings']}
assert set(reviews)=={r['id'] for r in base} and len(base)==20
runtime=json.loads((R/'runtime-summary.json').read_text());packages=json.loads((R/'source-package-check.json').read_text());assert len(runtime)==len(packages)==20 and all(x['exit_code']==0 for x in runtime)
entries=[]
for r in base:
 i=r['id'];e=r['original_review'];v=reviews[i]
 entries.append({'id':i,'disposition':'presentation-correction-candidate' if i=='bangladesh' else 'unchanged-with-explicit-limitations','correction_passes':1 if i=='bangladesh' else 0,'model_geometry_changed':False,'final_approved':False,'launch_ready':False,'original_observations':e['independent_visual']['assessment']['concrete_defects'],'independent_adjudication':v,'unresolved_owner_holds':e.get('missing_gates',[]),'inherited_holds':e.get('inherited_missing_gates',[]),'original_review_preserved_in':'baseline.json','fresh_runtime':next(x for x in runtime if x['id']==i),'fresh_source_archive':next(x for x in packages if x['id']==i),'remaining_visual_limitations':('Very small oblique motifs still lose detail; intentional segmented joins unchanged; physical-device performance unverified.' if i=='bangladesh' else v.get('rationale',v['observation']))})
out={'parent_commit':'3952a4eb1c57ca921c21d0aa774ab8b8752e3df7','parent_dispositions_sha256':hashlib.sha256(parent).hexdigest(),'preserved_collection_records':len(allrows['records']),'assigned_count':len(entries),'changed_viewers':['bangladesh'],'changed_models':[],'approved':0,'entries':entries}
(R/'dispositions.json').write_text(json.dumps(out,indent=2))
lines=['# Ordinary finish continuation — 20 exact candidates','', '## Result','One presentation-only correction: Bangladesh’s fine textile/trim resolves more clearly with a 2× drawing buffer on low-DPR screens. All model/source/export/material/pivot bytes remain unchanged. Nineteen candidates remain unchanged with individual limitations; this is not blanket approval or collection completion.','', 'The immutable parent at `3952a4eb1c57ca921c21d0aa774ab8b8752e3df7` and its 201-record disposition file are untouched. Full original reviews are preserved in `baseline.json`; `dispositions.json` preserves exact observations, per-ID rationale and owner holds.','', '## Fresh verification','- 20 hash-bound viewers: desktop/mobile closed/open captures. Independent visual review includes all 20 plus promotional references; original full-resolution captures retained.','- All 20: offline native desktop/mobile open/close, drag/touch, interrupted reset, reduced motion, full-open framing, no overflow or external requests, real corrupt-GLB and no-JS fallback. Shared assertions are labeled, not misrepresented as original asset suites.','- All 20 original ZIPs: hash/size, safe unique paths, CRC, full supported inner inventories and exact selected HTML/GLB/Blender payloads checked again.','- Bangladesh successor: same interaction gates at DPR 1/2/3; source/GLB parity reopened in Blender; two original motion/asset tests passed. Geometry/pivots untouched, so no new clearance sampling claimed.','- Bangladesh initial no-JS harness used an incorrect selector. Failure retained; corrected assertion targets the existing default poster. No fallback code changed.','', '## Per-ID dispositions','']
for e in entries:
 v=e['independent_adjudication'];lines += ['### '+e['id'],e['disposition'],v.get('rationale',v['observation']),v.get('bounded_recommendation',v.get('recommendation','')),'']
lines += ['## Source-mapping follow-up','Exact author sources for Djibouti and Tajikistan are retained in source-probes. Both project UVs per face axis on separately constructed panels/slabs/collars. The inspected rectangular transitions are not sufficient proof that an intended continuous surface is corrupt. Local-object mapping explains possible panel restarts, but authoring intent and acceptability remain owner decisions; no blanket re-UV or repaint is authorized by these observations.','', '## Remaining scope','No final art, rights, storage/preservation, authentic issuer/key/origin, real wallet/payment/chain, external security, economics/legal, mint/sale or production release hold is cleared. Sampling trials for Samoa, Southern Ocean and Tunisia were optional reviewer suggestions, not established defects; they remain unchanged. Comoros crater/material readability and all per-ID finish choices remain disclosed. No paid generation, nodes, funds, production docs/master edits or deployment. Preserve 201 one-of-ones, one inner NFT plus detached signed record; no accessory/certificate NFT or reuse-support claim.','', '## Recommended next step','Review the Bangladesh before/after candidate and recorded per-ID aesthetic decisions. Do not commission another blanket polish pass or declare the collection finished.']
(R/'README.md').write_text('\n'.join(lines)+'\n')
print(json.dumps({'ids':len(entries),'archive_members':sum(a['members'] for r in packages for a in r['archives']),'changed_viewers':1,'model_changes':0,'approved':0}))
